from pathlib import Path
import base64
import gzip
import re

ROOT = Path(__file__).resolve().parents[4]
TASKS = ROOT / "project/TASKS.yaml"
DECISIONS = ROOT / "project/DECISION_LOG.md"
REPORT = ROOT / "project/planning/transitions/stage4-to-stage5/TRANSITION_REPORT.md"
S6 = ROOT / "project/planning/transitions/stage4-to-stage5/STAGE6_PROVISIONAL.yaml"
S7 = ROOT / "project/planning/transitions/stage4-to-stage5/STAGE7_PROVISIONAL.yaml"
BATCHES = ROOT / "project/planning/transitions/stage4-to-stage5/STAGE5_FINAL_BATCHES.md"

SUFFIX_B64 = """"""


def section(text: str, task_id: str) -> str:
    marker = f"- id: {task_id}\n"
    start = text.index(marker)
    nxt = text.find("\n- id: ", start + len(marker))
    return text[start:] if nxt < 0 else text[start:nxt + 1]


def apply() -> None:
    tasks = TASKS.read_text(encoding="utf-8")
    if "- id: AICAD-101\n" not in tasks:
        assert "- id: AICAD-100A\n" in tasks
        suffix = gzip.decompress(base64.b64decode(SUFFIX_B64)).decode("utf-8").rstrip() + "\n"
        tasks = tasks.rstrip() + "\n" + suffix
        TASKS.write_text(tasks, encoding="utf-8")

    decisions = DECISIONS.read_text(encoding="utf-8")
    if "## DL-34:" not in decisions:
        marker = "## General constraint on D21-D30 during Stage 4"
        assert marker in decisions
        dl34 = """## DL-34: Stage 4 passed — owner approval of the final AICAD-100A gate state

- Date: 2026-09-16
- Resolves: the Stage-4 owner hard gate after AICAD-100A; this is a stage-gate approval record, not a new D-numbered semantic decision.
- Decision: **Stage 4 passed.** The owner accepts the completed Stage-4 implementation through `AICAD-100A` and the final updated `project/gates/stage-4-gate.md`. The accepted implementation merge is `564e6790b67bf2a5b489bca2003a5084a959e937`; the durable owner-approval record and planning base on `main` is `35547025bbe32f350bcdaf2c1556ed2482a2cada` (`project/approvals/STAGE4_OWNER_APPROVAL.md`). This approval authorizes the bounded Stage-4 -> Stage-5 transition/roadmap-freeze pass only. It does **not** authorize `AICAD-101` or any Stage-5 implementation. Stage-5 implementation begins only after the owner reviews and merges the finalized transition queue and `claude/aicad-stage5-dev` is created from that exact approved merged HEAD.
- Rationale: the owner explicitly accepted the final AICAD-100A gate state after the production semantic-reference completion pass. Recording the approval in the canonical decision log keeps `CURRENT_STAGE.md`, `SESSION_HANDOFF.md`, the gate evidence, and future zero-context worker instructions consistent.
- Alternatives considered: leave the approval only in `project/approvals/STAGE4_OWNER_APPROVAL.md` (rejected because transition governance explicitly requires a decision-log record); treat Stage-4 approval as automatic Stage-5 implementation authorization (rejected because the transition queue itself still requires owner review/merge).
- Affected tasks: closes the Stage-4 gate through `AICAD-100A`; permits planning-only finalization of `AICAD-101..AICAD-130`; preserves all resolved owner decisions D1-D31, including D7 fail-closed reference behavior and disabled automatic fingerprint recovery.
- Supersedes: stale text that described Stage 4 as awaiting owner approval; it does not supersede a semantic owner decision.

---

"""
        DECISIONS.write_text(decisions.replace(marker, dl34 + marker, 1), encoding="utf-8")

    report = REPORT.read_text(encoding="utf-8")
    if "## Task-list quality comparison\n" not in report:
        marker = "## Stage promotion policy\n"
        assert marker in report
        quality = """## Task-list quality comparison

The canonical historical queue begins at **AICAD-001**; there is no `AICAD-000` entry. The final Stage-5 range therefore continues the repository's existing numbering/suffix convention after `AICAD-100A` by using `AICAD-101..AICAD-130`, without renumbering historical work.

The final entries were compared against the complete historical `AICAD-001..AICAD-100A` queue and, in particular, the more exact remediation/gate precedents (`AICAD-057B..057F`, `AICAD-064A`, `AICAD-075A`, `AICAD-076A`, `AICAD-079A..079C`, `AICAD-099A`, and `AICAD-100A`). Stage 5 deliberately uses the stronger later-task style rather than the older generic “focused implementation” placeholder style: every `AICAD-101..130` entry has explicit dependency edges, current normative/evidence references, observable acceptance criteria, concrete verification commands, a dedicated report path, and task-specific escalation conditions.

Queue-integrity checks performed in this transition pass verify that the Stage-5 IDs are unique and contiguous, every Stage-5 dependency points only to an earlier existing task, every Stage-5 task remains `todo`/non-authorized pending the owner transition gate, checkpoints terminate their intended capability slices, and no Stage-6/7 local task was inserted into the active executable queue. The fixed batch view and canonical task entries agree on the 30-task range and final owner gate.

The Stage-6/7 provisional files were also rechecked after this comparison: they retain local IDs only, preserve owner-decision/evidence-sensitive annotations, and do not pull in distributed execution, universal multi-representation geometry, giant provenance ontology work, multiple production assembly solvers, a full conventional GUI, native plugin ABI, or arbitrary external-CAD intent reconstruction.

"""
        REPORT.write_text(report.replace(marker, quality + marker, 1), encoding="utf-8")


def validate() -> None:
    tasks = TASKS.read_text(encoding="utf-8")
    ids = re.findall(r"^- id: (AICAD-[0-9]+[A-Z]?)$", tasks, re.M)
    assert ids and ids[0] == "AICAD-001"
    assert "AICAD-000" not in ids
    assert len(ids) == len(set(ids)), "duplicate AICAD task ID"
    stage5 = [f"AICAD-{n}" for n in range(101, 131)]
    observed = [x for x in ids if re.fullmatch(r"AICAD-1(?:0[1-9]|[12][0-9]|30)", x)]
    assert observed == stage5, (observed, stage5)
    order = {task_id: i for i, task_id in enumerate(ids)}
    for task_id in stage5:
        s = section(tasks, task_id)
        for field in (
            "  stage: 5\n", "  status: todo\n", "  depends_on:\n", "  plan_references:\n",
            "  acceptance:\n", "  required_checks:\n", f"  report: project/reports/{task_id}.md\n", "  escalate_if:\n",
        ):
            assert field in s, f"{task_id}: missing {field.strip()}"
        assert "Focused implementation plus task-specific tests/benchmarks" not in s
        acceptance = s.split("  acceptance:\n", 1)[1].split("  required_checks:\n", 1)[0]
        assert len(re.findall(r"^  - ", acceptance, re.M)) >= 3, f"{task_id}: acceptance too thin"
        checks = s.split("  required_checks:\n", 1)[1].split("  report:", 1)[0]
        assert len(re.findall(r"^  - ", checks, re.M)) >= 3, f"{task_id}: checks too thin"
        dep_block = s.split("  depends_on:\n", 1)[1].split("  plan_references:\n", 1)[0]
        deps = re.findall(r"^  - (AICAD-[0-9]+[A-Z]?)$", dep_block, re.M)
        assert deps, f"{task_id}: missing dependency"
        for dep in deps:
            assert dep in order and order[dep] < order[task_id], f"{task_id}: invalid dependency {dep}"
    assert "automatic fingerprint recovery remains disabled" in tasks.lower() or "fingerprint auto-recovery" in tasks.lower()

    s6_ids = re.findall(r"^- id: (S6-[0-9]{3})$", S6.read_text(encoding="utf-8"), re.M)
    s7_ids = re.findall(r"^- id: (S7-[0-9]{3})$", S7.read_text(encoding="utf-8"), re.M)
    assert s6_ids == [f"S6-{n:03d}" for n in range(1, 31)]
    assert s7_ids == [f"S7-{n:03d}" for n in range(1, 31)]

    batches = BATCHES.read_text(encoding="utf-8")
    assert "AICAD-101` through `AICAD-130" in batches
    assert "S5-00" in batches and "S5-10" in batches
    assert "## DL-34:" in DECISIONS.read_text(encoding="utf-8")
    report = REPORT.read_text(encoding="utf-8")
    assert "## Task-list quality comparison" in report
    assert "Automatic geometry-fingerprint recovery is intentionally excluded" in report
    print("Stage-5 transition planning audit OK")


if __name__ == "__main__":
    apply()
    validate()
